INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.a', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART', 'a', 'analyse a play performance', 'kicd_read') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.b', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART', 'b', 'examine ethical practices in sports', 'kicd_read') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.c', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART', 'c', 'analyse a solo vocal piece of music', 'kicd_read') ON CONFLICT (code) DO NOTHING;
