INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.e', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART', 'e', 'appreciate the role of analysis in adding value to Creative Arts and Sports', 'kicd_read') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS', 'CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS', 'creative_arts', 9, 'Identify careers and entrepreneurial opportunities in Creative Arts and Sports', ARRAY['CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.a', 'CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.b']::text[], 'The child names careers in each area (visual arts: graphic designer, photographer, painter; physical education and sports: coach, referee, physiotherapist, athlete; music: musician, sound engineer, music teacher; theatre: actor, director, set designer), says what each does, and names entrepreneurial opportunities (selling crafts, event photography, a dance troupe, a sports academy, hiring out sound equipment). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.1.1, CREA.G9.RUBRIC.1.2, CREA.G9.RUBRIC.1.3), never as a phone question: b) illustrate entrepreneurial opportunities in Creative Arts and Sports.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 9, 'Describe the elements of a play', ARRAY['CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.a']::text[], 'The child names the elements of a play (plot, characters, setting, theme, conflict, resolution, dialogue and stage directions) and says what each is in a short play they have read or watched. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 9, 'Tell power and reaction time from the other components of fitness', ARRAY['CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.b']::text[], 'The child says power is strength used quickly (a standing long jump, a vertical jump, a shot put) and reaction time is how fast the body responds to a signal (a sprint start, catching a dropped ruler), and picks an activity that trains each. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.1.1, CREA.G9.RUBRIC.1.2, CREA.G9.RUBRIC.1.3), never as a phone question: b) perform activities demonstrating the components of fitness.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 9, 'Name pitches on the grand stave', ARRAY['CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.c']::text[], 'The child says the grand stave joins the treble and bass staves with a brace, names the lines and spaces of both (treble E G B D F and F A C E; bass G B D F A and A C E G), and places middle C on the ledger line between them. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 9, 'Group notes in four-four time with note extension', ARRAY['CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.d']::text[], 'The child says four-four time has four crotchet beats in a bar (beat 1 strong, beat 3 medium), that a dot adds half a note''s value (dotted crotchet one and a half beats, dotted minim three) and a tie joins two notes of the same pitch into one sound, and checks that each bar adds up to four. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 9, 'Build the scale of F major', ARRAY['CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.e']::text[], 'The child says F major has one flat, B flat, and its notes are F G A B-flat C D E F, starting and ending on F, and that the flat applies to every B in the piece. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY', 'CREA.G9.CREATI.DRAWING_AND_PAINTING', 'creative_arts', 9, 'Say what harmony or unity is in a picture and how it is made', ARRAY['CREA.G9.CREATI.DRAWING_AND_PAINTING.a']::text[], 'The child says harmony (unity) is when all the parts of a picture look as if they belong together, made by repeating similar colours, shapes, lines or textures, and tells it from contrast and dominance. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: d) paint a scenery composition to express harmony/unity.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.ANALOGOUS', 'CREA.G9.CREATI.DRAWING_AND_PAINTING', 'creative_arts', 9, 'Classify analogous colours on a colour wheel', ARRAY['CREA.G9.CREATI.DRAWING_AND_PAINTING.b']::text[], 'The child says analogous colours sit next to each other on the colour wheel (such as yellow, yellow-orange and orange, or blue, blue-green and green), give a calm, harmonious effect, and tells them from complementary colours, which sit opposite. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: c) illustrate a colour gradation strip for colour harmony.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.RHYTHM.NOTE_EXTENSION', 'CREA.G9.CREATI.RHYTHM', 'creative_arts', 9, 'Describe the effect of note extension on rhythmic patterns', ARRAY['CREA.G9.CREATI.RHYTHM.a']::text[], 'The child says a dot or a tie makes a note last longer (a dotted crotchet one and a half beats, a crotchet tied to a quaver the same), that this gives long-short patterns and moves the stress, and that a dotted note is often followed by a shorter note to complete the beat. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: b) compose a four-bar rhythmic pattern in 4 4 time; c) notate four-bar rhythms in 4 time from 4 dictation.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.TRIPLE_JUMP', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC', 'creative_arts', 9, 'Describe the phases of the triple jump', ARRAY['CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.a']::text[], 'The child orders the phases (approach run, hop, step, jump, landing), says the hop lands on the take-off foot, the step lands on the other foot and the jump ends in the pit on both feet, and that the jump is measured from the take-off board. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: b) perform Triple jump for skill acquisition.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.LONG_DISTANCE', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC', 'creative_arts', 9, 'Identify long distance races and their techniques', ARRAY['CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.c']::text[], 'The child names long distance races (5 000 m, 10 000 m, the marathon, cross-country) and their technique: an even pace, relaxed arm action, a short economical stride, steady breathing and a finishing kick, and says why Kenyan runners pace a race. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: d) perform techniques for long distance running.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.MOSAIC', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC', 'creative_arts', 9, 'Explore the characteristics of a mosaic', ARRAY['CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.e']::text[], 'The child says a mosaic is a picture made of small pieces (tesserae) of one material (paper, seeds, stones, tiles) placed close together with small even gaps (grout lines), following a planned design, with colour used to show shape and light. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: f) create a mosaic pictorial composition inspired by an athletic event.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.MELODY.VARIATION', 'CREA.G9.CREATI.MELODY', 'creative_arts', 9, 'Describe the use of variation in composing a melody', ARRAY['CREA.G9.CREATI.MELODY.a']::text[], 'The child says variation repeats a phrase with a change (in some pitches, in the rhythm, or moved higher or lower as a sequence) so the melody is both familiar and interesting, and that an answering phrase is often a variation of the opening phrase. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: b) compose a four-bar melody in F Major and 4 time, 4; c) notate four-bar, melodies in 4 time, 4; d) perform melodies in F major and 4 time, 4.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.RUGBY.RUGBY', 'CREA.G9.CREATI.RUGBY', 'creative_arts', 9, 'Distinguish the passes and kicks in rugby', ARRAY['CREA.G9.CREATI.RUGBY.a']::text[], 'The child tells the basic (lateral) pass, the spin pass (the ball spins for a long, fast pass) and the pop pass (a short, soft lift to a team mate running close), says the ball may only be passed sideways or backwards, and tells the place kick (off a kicking tee) from the drop kick (the ball touches the ground before it is kicked). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: b) perform passing skills in Rugby; c) perform kick techniques in Rugby.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.PHOTOGRAPHY.VIEWPOINTS', 'CREA.G9.CREATI.PHOTOGRAPHY', 'creative_arts', 9, 'Identify viewpoints in photography', ARRAY['CREA.G9.CREATI.PHOTOGRAPHY.a']::text[], 'The child names the bird''s eye view (camera high, looking down), the normal or eye-level view and the worm''s eye view (camera low, looking up), and says what each does to the subject (small, natural, tall and powerful). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: b) take photographs of a scenery in viewpoint for showcase; c) present the photographs for appreciation.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.DESCANT_RECORDER.F_FINGERING', 'CREA.G9.CREATI.DESCANT_RECORDER', 'creative_arts', 9, 'Identify the fingering of the notes of the scale of F major on the descant recorder', ARRAY['CREA.G9.CREATI.DESCANT_RECORDER.a']::text[], 'The child says the F major scale on the recorder is F G A B-flat C D E F, that low F needs the right hand as well as all left-hand holes, and that B flat uses a cross-fingering, not the fingering of B, and reads the flat in the key signature before playing. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: b) play the scale of F major from staff notation on a descant recorder; c) perform a solo piece in F major on a descant recorder, applying correct playing techniques.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.PLAY.SCRIPT_FORMAT', 'CREA.G9.CREATI.PLAY', 'creative_arts', 9, 'Describe the format of a play script', ARRAY['CREA.G9.CREATI.PLAY.a']::text[], 'The child names the parts of a play script (title, cast list, acts and scenes, the character''s name before each speech, dialogue, and stage directions in brackets or italics) and says stage directions are read and acted, not spoken aloud. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: b) create a one act play addressing a societal issue; c) act a role in a play performance.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.BASKETBALL', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI', 'creative_arts', 9, 'Describe passing and dribbling in basketball', ARRAY['CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.a', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.b']::text[], 'The child describes the chest, bounce and overhead passes and when each is used, high dribbling (for speed in open space) and low dribbling (to protect the ball near a defender), and says a player may not walk with the ball (travelling) or dribble, stop and dribble again (double dribble). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: a) perform passes in Basketball for skill acquisition; b) execute dribbling in Basketball for skill acquisition.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.LOGO', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI', 'creative_arts', 9, 'Say what makes a good logo for a team', ARRAY['CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.c']::text[], 'The child says a logo is a simple symbol, name or letter combination that stands for a team, and that a good one is simple, easy to recognise and remember, uses few colours, works small and large, and fits the team''s name or spirit. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: c) design logo for a Basketball team.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.COIL_POTTERY', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS', 'creative_arts', 9, 'Describe the coil technique in pottery', ARRAY['CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.a']::text[], 'The child orders coil pottery: prepare the clay (remove impurities, knead and wedge), roll coils of even thickness, score and join each coil with slip, smooth the inside, decorate when slightly dry by incising, and dry slowly in the shade. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: b) model a vessel using coil method.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.TWILL', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS', 'creative_arts', 9, 'Describe a frame loom and the 2/1 twill weave', ARRAY['CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.c', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.d']::text[], 'The child says a frame loom holds the warp threads tight on a frame, and in a 2/1 twill the weft passes over two warp threads and under one, moving one thread along on each row so that diagonal lines form, unlike the plain weave of over one, under one. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: c) make a frame loom for weaving; d) make a fabric using 2/1 twill weaving technique; e) display and critique own and others’ woven articles.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.SWIMMING.DIVE_BUTTERFLY', 'CREA.G9.CREATI.SWIMMING', 'creative_arts', 9, 'Describe the standing dive and the butterfly stroke', ARRAY['CREA.G9.CREATI.SWIMMING.a']::text[], 'The child describes the standing dive (toes over the edge, arms stretched over the head, bend, push and enter hands first, only into deep water with a lifeguard) and the butterfly (body flat and wave-like, both arms over the water together, dolphin kick with legs together, breathing forward). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: b) perform a standing dive in swimming; c) perform the butterfly stroke in swimming.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_.BOARD_GAMES', 'CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_', 'creative_arts', 9, 'Identify indigenous board games and what they build', ARRAY['CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_.a']::text[], 'The child names indigenous board games (bao and other games of sowing seeds in pits, played on boards or in the ground), says how a turn is played (sowing seeds one by one into the next pits and capturing), and that they build counting, planning, patience and mental health. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.2.1, CREA.G9.RUBRIC.2.2, CREA.G9.RUBRIC.2.3), never as a phone question: b) perform different indigenous board games; c) perform indigenous board games to background music for enjoyment.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.PERFORMANCE_ANALYSIS', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 9, 'Analyse a play performance and a solo vocal piece', ARRAY['CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.a', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.c']::text[], 'The child analyses a play performance by its theme, setting, conflict, resolution, use of voice and body, props, costume and audience involvement, and a solo vocal piece by its melody, dynamics, tempo, diction, message and accompaniment, backing each point with something seen or heard. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_ETHICS', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 9, 'Examine ethical practices in sports', ARRAY['CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.b']::text[], 'The child names ethical practices in sport (no doping, fair play, honest age and identity, no match fixing, respect for officials and opponents, safeguarding) and says why doping is banned (it is cheating and harms health). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 9, 'Critique exhibited artworks', ARRAY['CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.d']::text[], 'The child critiques an artwork in four steps (describe what is seen, analyse the elements and principles used, interpret the meaning, judge with reasons), kindly and with evidence from the work. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G9.RUBRIC.3.1), never as a phone question: d) critique exhibited artworks for inspiration.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS', 'CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES', 'skill', 'essential', 'Earning a living is one of the roles of the arts and sport (Grade 8). Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS', 'SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS', 'skill', 'helpful', 'The senior school pathways (Grade 9 Social Studies) include the Arts and Sports Science pathway these careers follow. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS', 'skill', 'essential', 'The elements of a story (Grade 7) are shared by a play. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS', 'ENGL.G9.READIN.T1_PLAY_STRUCTURE_AND_S.PL_STRUCTURE', 'skill', 'helpful', 'The setting and order of a play (Grade 9 English) are read in the same term. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY', 'skill', 'essential', 'Endurance and agility (Grade 8) come before power and reaction time. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS', 'skill', 'essential', 'The full list of fitness components (Grade 7) includes these two. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF', 'skill', 'essential', 'The bass staff (Grade 8) is the lower half of the grand stave. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES', 'skill', 'essential', 'The treble staff (Grade 7) is the upper half. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34', 'skill', 'essential', 'Grouping in three-four time and the dotted minim (Grade 8) come before four-four with note extension. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44', 'MATH.G7.NUMBER.FRACTIONS.ADD_UNLIKE_FRACTIONS', 'skill', 'helpful', 'Adding halves and quarters (Grade 7 Maths) is how dotted notes and quavers fill a bar. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR', 'skill', 'essential', 'Building G major with one sharp (Grade 8) is the same method for F major with one flat. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR', 'CREA.G7.CREATI.MELODY.MELODY_QUALITIES', 'skill', 'helpful', 'C major (Grade 7) is the key with no sharps or flats that F major is compared with. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY', 'CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE', 'skill', 'essential', 'Dominance (Grade 8) is the principle compared with harmony. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
