INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE', 'CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY', 'skill', 'helpful', 'Harmony, with dominance and balance, is a principle named when analysing an artwork. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
