INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS.M_CA9_CR_ONLY_PERFORMER', 'CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS', 'Thinks the only careers are performing ones (singer, athlete, actor).', '{"question":"Which is a career in Creative Arts and Sports?","wrong_answer":"only being a famous singer","correct_answer":"many, such as a sound engineer, a referee or a set designer"}'::jsonb, 'Performers are the people seen on TV.', 'Offer "only being a famous singer" next to the right answer and ask the question again in a new context.', 'List the people behind one concert or one match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS.M_CA9_CR_NO_MONEY', 'CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS', 'Thinks the arts and sport cannot earn a steady living.', '{"question":"Can a photographer earn a living?","wrong_answer":"no, it is only a hobby","correct_answer":"yes, at events, for businesses and in media"}'::jsonb, 'The child has heard adults call the arts a hobby.', 'Offer "no, it is only a hobby" next to the right answer and ask the question again in a new context.', 'Count the paid jobs at one wedding: photographer, decorator, DJ, caterer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS.M_CA9_CR_AREA_MIX', 'CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS', 'Puts a physiotherapist under music.', '{"question":"Which area does a sports physiotherapist work in?","wrong_answer":"music","correct_answer":"physical education and sports"}'::jsonb, 'The child sorts by the word "therapy", not by the field.', 'Offer "music" next to the right answer and ask the question again in a new context.', 'Ask: who does this person help, musicians or athletes?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS.M_CA9_CR_ENTERPRISE_JOB', 'CREA.G9.FOUNDA.CAREERS_IN_CREATIVE_ARTS.CAREERS', 'Thinks entrepreneurship means only being employed by a company.', '{"question":"What is an entrepreneurial opportunity in Creative Arts?","wrong_answer":"working for a big company","correct_answer":"starting your own business, such as selling crafts or event photography"}'::jsonb, 'The child mixes having a job with starting a business.', 'Offer "working for a big company" next to the right answer and ask the question again in a new context.', 'Compare an employee with a learner who sells beadwork at a market.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS.M_CA9_PE_CONFLICT_FIGHT', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS', 'Thinks conflict in a play means a physical fight.', '{"question":"What is conflict in a play?","wrong_answer":"a fight with blows","correct_answer":"the struggle or problem the characters face"}'::jsonb, 'In daily speech conflict means fighting.', 'Offer "a fight with blows" next to the right answer and ask the question again in a new context.', 'Find the conflict in a play with no fighting at all.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS.M_CA9_PE_RESOLUTION_START', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS', 'Says the resolution comes at the start of the play.', '{"question":"Where does the resolution come in a play?","wrong_answer":"at the start","correct_answer":"near the end, when the conflict is settled"}'::jsonb, 'The child mixes "resolution" with "introduction".', 'Offer "at the start" next to the right answer and ask the question again in a new context.', 'Order the parts of a known play: introduction, conflict, climax, resolution.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS.M_CA9_PE_THEME_PLOT', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS', 'Gives the plot when asked for the theme.', '{"question":"What is the theme of a play?","wrong_answer":"what happens first, then next","correct_answer":"the main idea it is about, such as honesty"}'::jsonb, 'Retelling the events is easier than naming the idea.', 'Offer "what happens first, then next" next to the right answer and ask the question again in a new context.', 'Ask "what is the play teaching?" after retelling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS.M_CA9_PE_DIRECTIONS_SPOKEN', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.PLAY_ELEMENTS', 'Thinks stage directions are spoken by the actors.', '{"question":"Are stage directions spoken aloud in a performance?","wrong_answer":"yes","correct_answer":"no; they are acted, not spoken"}'::jsonb, 'The child reads everything on the page as lines.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Act out "(she opens the door slowly)" without saying it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER.M_CA9_FP_POWER_STRENGTH', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER', 'Thinks power is the same as strength.', '{"question":"What is the difference between strength and power?","wrong_answer":"they are the same","correct_answer":"power is strength used quickly"}'::jsonb, 'Both words are used for strong people.', 'Offer "they are the same" next to the right answer and ask the question again in a new context.', 'Compare lifting a bag slowly (strength) and a vertical jump (power).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER.M_CA9_FP_REACTION_SPEED', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER', 'Thinks reaction time is how fast you run.', '{"question":"What is reaction time?","wrong_answer":"how fast you run","correct_answer":"how quickly the body responds to a signal"}'::jsonb, 'Both are about being quick.', 'Offer "how fast you run" next to the right answer and ask the question again in a new context.', 'Do the ruler-drop test: catch it as fast as you can.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER.M_CA9_FP_ACTIVITY', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER', 'Picks a long jog as training for power.', '{"question":"Which activity trains power?","wrong_answer":"a long, slow jog","correct_answer":"standing long jumps"}'::jsonb, 'The child thinks any exercise builds every component.', 'Offer "a long, slow jog" next to the right answer and ask the question again in a new context.', 'Match each activity to what it trains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER.M_CA9_FP_START_REACTION', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_POWER', 'Says a sprint start trains endurance.', '{"question":"A sprinter practises starts to the gun. What does this train?","wrong_answer":"endurance","correct_answer":"reaction time"}'::jsonb, 'The child links all running with endurance.', 'Offer "endurance" next to the right answer and ask the question again in a new context.', 'Practise starts to a clap and time the response.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE.M_CA9_GS_MIDDLE_C_TWO', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE', 'Thinks there are two different middle Cs on the grand stave.', '{"question":"Is middle C on the treble staff the same note as middle C on the bass staff?","wrong_answer":"no, they are different notes","correct_answer":"yes, the same note, written on a ledger line from either staff"}'::jsonb, 'It is written in two places.', 'Offer "no, they are different notes" next to the right answer and ask the question again in a new context.', 'Play middle C and show both ways of writing it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE.M_CA9_GS_BASS_AS_TREBLE', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE', 'Reads bass staff notes with the treble names.', '{"question":"What is the note on the bottom line of the bass staff?","wrong_answer":"E","correct_answer":"G"}'::jsonb, 'The treble names were learnt first and are used for both staves.', 'Offer "E" next to the right answer and ask the question again in a new context.', 'Check the clef before naming any note.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE.M_CA9_GS_BRACE', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE', 'Thinks the brace joins any two staves of different songs.', '{"question":"What does the brace on a grand stave show?","wrong_answer":"two different songs","correct_answer":"the two staves are played together as one part"}'::jsonb, 'The child has not seen piano music.', 'Offer "two different songs" next to the right answer and ask the question again in a new context.', 'Show piano music: both hands read at once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE.M_CA9_GS_HIGH_LOW', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.GRAND_STAVE', 'Thinks the bass staff is for high notes.', '{"question":"Which staff of the grand stave holds the low notes?","wrong_answer":"the treble staff","correct_answer":"the bass staff"}'::jsonb, 'The child mixes up "bass" and "treble".', 'Offer "the treble staff" next to the right answer and ask the question again in a new context.', 'Sing low and point to the bass staff.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44.M_CA9_T4_DOT_DOUBLE', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44', 'Thinks a dot doubles a note''s value.', '{"question":"How many beats is a dotted crotchet?","wrong_answer":"two","correct_answer":"one and a half"}'::jsonb, 'The child thinks the dot adds the whole note again.', 'Offer "two" next to the right answer and ask the question again in a new context.', 'A crotchet is 1; half of 1 is a half; 1 + a half = one and a half.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44.M_CA9_T4_TIE_DIFFERENT', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44', 'Ties two notes of different pitch.', '{"question":"Can a tie join a C and a D?","wrong_answer":"yes","correct_answer":"no; a tie joins two notes of the same pitch"}'::jsonb, 'The child mixes a tie with a slur.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Show a tie (same pitch, held) and a slur (different pitches, smooth).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44.M_CA9_T4_FIVE_BEATS', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44', 'Writes a bar of four-four time with five beats.', '{"question":"A bar has a dotted minim and a minim. Is it a correct bar of four-four?","wrong_answer":"yes","correct_answer":"no; it has five beats"}'::jsonb, 'The child adds notes by eye.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Write the beat count under each note.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44.M_CA9_T4_ACCENT_ALL', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_44', 'Stresses every beat equally in four-four time.', '{"question":"Which beats are strong in four-four time?","wrong_answer":"all four equally","correct_answer":"beat 1 strongest, beat 3 medium"}'::jsonb, 'The child counts evenly without stress.', 'Offer "all four equally" next to the right answer and ask the question again in a new context.', 'Count ONE two THREE four while stepping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR.M_CA9_FM_SHARP', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR', 'Puts a sharp in F major.', '{"question":"F major has one...","wrong_answer":"sharp","correct_answer":"flat"}'::jsonb, 'G major, with one sharp, was learnt first.', 'Offer "sharp" next to the right answer and ask the question again in a new context.', 'Write F G A B C D E F and play it: B must be lowered.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR.M_CA9_FM_WHICH_FLAT', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR', 'Names E as the flat note in F major.', '{"question":"Which note is flat in F major?","wrong_answer":"E","correct_answer":"B"}'::jsonb, 'The child guesses the note before F.', 'Offer "E" next to the right answer and ask the question again in a new context.', 'Count the steps from F: the fourth note, B, is lowered.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR.M_CA9_FM_HOME', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR', 'Ends an F major scale on C.', '{"question":"On which note does F major start and end?","wrong_answer":"C","correct_answer":"F"}'::jsonb, 'C major feels like home from Grade 7.', 'Offer "C" next to the right answer and ask the question again in a new context.', 'The key name is the home note.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR.M_CA9_FM_FLAT_ONCE', 'CREA.G9.FOUNDA.COMPONENTS_OF_CREATIVE_A.F_MAJOR', 'Flattens only the first B in a piece.', '{"question":"In F major, is every B played as B flat?","wrong_answer":"only the first one","correct_answer":"yes, every B"}'::jsonb, 'The child treats the key signature like a one-time accidental.', 'Offer "only the first one" next to the right answer and ask the question again in a new context.', 'Circle every B in an F major tune.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY.M_CA9_HM_ALL_SAME', 'CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY', 'Thinks harmony means every part is exactly the same colour and shape.', '{"question":"Does harmony mean everything in a picture is identical?","wrong_answer":"yes","correct_answer":"no; parts are similar enough to belong together"}'::jsonb, 'The child takes "unity" to mean sameness.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Show a landscape in greens and blues with varied shapes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY.M_CA9_HM_CONTRAST', 'CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY', 'Uses strong contrasting colours to show harmony.', '{"question":"Which colours give harmony: red and green, or yellow and orange?","wrong_answer":"red and green","correct_answer":"yellow and orange"}'::jsonb, 'Bright contrasts catch the eye, so the child thinks they work best.', 'Offer "red and green" next to the right answer and ask the question again in a new context.', 'Paint both pairs and ask which feels calm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY.M_CA9_HM_DOMINANCE', 'CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY', 'Says harmony is when one feature stands out.', '{"question":"A picture has one big bright feature that catches the eye. Which principle is that?","wrong_answer":"harmony","correct_answer":"dominance"}'::jsonb, 'Both are principles learnt in Grades 8 and 9.', 'Offer "harmony" next to the right answer and ask the question again in a new context.', 'Ask: does one thing stand out, or does everything belong together?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY.M_CA9_HM_REPEAT_BAD', 'CREA.G9.CREATI.DRAWING_AND_PAINTING.HARMONY', 'Thinks repeating shapes in a picture is boring and should be avoided.', '{"question":"How can an artist create unity in a picture?","wrong_answer":"never repeat any shape","correct_answer":"repeat similar shapes, colours or lines"}'::jsonb, 'The child thinks variety is always better.', 'Offer "never repeat any shape" next to the right answer and ask the question again in a new context.', 'Find repeated shapes in a woven mat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.ANALOGOUS.M_CA9_AN_OPPOSITE', 'CREA.G9.CREATI.DRAWING_AND_PAINTING.ANALOGOUS', 'Says analogous colours sit opposite each other on the wheel.', '{"question":"Where are analogous colours on the colour wheel?","wrong_answer":"opposite each other","correct_answer":"next to each other"}'::jsonb, 'Grade 8 complementary colours were opposite, so the child keeps that rule.', 'Offer "opposite each other" next to the right answer and ask the question again in a new context.', 'Point at three neighbours on the wheel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.ANALOGOUS.M_CA9_AN_PAIR', 'CREA.G9.CREATI.DRAWING_AND_PAINTING.ANALOGOUS', 'Picks blue and orange as analogous.', '{"question":"Which group is analogous?","wrong_answer":"blue and orange","correct_answer":"blue, blue-green and green"}'::jsonb, 'The child remembers blue and orange as a pair from Grade 8.', 'Offer "blue and orange" next to the right answer and ask the question again in a new context.', 'Find each colour on the wheel and check if they touch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.ANALOGOUS.M_CA9_AN_ANY_THREE', 'CREA.G9.CREATI.DRAWING_AND_PAINTING.ANALOGOUS', 'Thinks any three colours are analogous.', '{"question":"Are red, yellow and blue analogous?","wrong_answer":"yes","correct_answer":"no; they are the primaries, spread apart on the wheel"}'::jsonb, 'The child thinks "analogous" means a group of three.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Mark red, yellow and blue on the wheel: they are far apart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DRAWING_AND_PAINTING.ANALOGOUS.M_CA9_AN_MOOD', 'CREA.G9.CREATI.DRAWING_AND_PAINTING.ANALOGOUS', 'Thinks analogous colours give a loud, clashing effect.', '{"question":"What effect do analogous colours usually give?","wrong_answer":"loud and clashing","correct_answer":"calm and harmonious"}'::jsonb, 'Bright paint looks loud to the child whatever its neighbours.', 'Offer "loud and clashing" next to the right answer and ask the question again in a new context.', 'Compare an analogous strip with a complementary strip.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.RHYTHM.NOTE_EXTENSION.M_CA9_NE_DOTTED_EVEN', 'CREA.G9.CREATI.RHYTHM.NOTE_EXTENSION', 'Claps a dotted crotchet and quaver as two even notes.', '{"question":"How does a dotted crotchet followed by a quaver sound?","wrong_answer":"two even notes","correct_answer":"long, then short"}'::jsonb, 'The child claps every pair evenly.', 'Offer "two even notes" next to the right answer and ask the question again in a new context.', 'Say "taa-i te" and clap long-short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.RHYTHM.NOTE_EXTENSION.M_CA9_NE_TIE_SOUND_TWICE', 'CREA.G9.CREATI.RHYTHM.NOTE_EXTENSION', 'Sounds both notes of a tie separately.', '{"question":"How many times do you sound two tied notes?","wrong_answer":"twice","correct_answer":"once, held for both values"}'::jsonb, 'The child sees two notes and plays two.', 'Offer "twice" next to the right answer and ask the question again in a new context.', 'Clap a tied pair as one long clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.RHYTHM.NOTE_EXTENSION.M_CA9_NE_DOT_REST', 'CREA.G9.CREATI.RHYTHM.NOTE_EXTENSION', 'Thinks a dot after a note means a short silence.', '{"question":"What does a dot after a note do?","wrong_answer":"adds a short silence","correct_answer":"makes the note longer by half its value"}'::jsonb, 'The dot looks like a small rest.', 'Offer "adds a short silence" next to the right answer and ask the question again in a new context.', 'Clap a crotchet, then a dotted crotchet; hear it held longer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.RHYTHM.NOTE_EXTENSION.M_CA9_NE_NO_EFFECT', 'CREA.G9.CREATI.RHYTHM.NOTE_EXTENSION', 'Thinks note extension does not change the feel of a rhythm.', '{"question":"Does adding dots change how a rhythm feels?","wrong_answer":"no","correct_answer":"yes; it gives long-short patterns and moves the stress"}'::jsonb, 'The child counts beats but does not listen to the feel.', 'Offer "no" next to the right answer and ask the question again in a new context.', 'Clap a plain and a dotted version of one bar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.TRIPLE_JUMP.M_CA9_TJ_HOP_OTHER_FOOT', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.TRIPLE_JUMP', 'Lands the hop on the other foot.', '{"question":"In the triple jump, which foot does the hop land on?","wrong_answer":"the other foot","correct_answer":"the same foot you took off from"}'::jsonb, 'The child thinks every phase changes feet.', 'Offer "the other foot" next to the right answer and ask the question again in a new context.', 'Chalk the pattern: right, right, left, both (for a right-foot take-off).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.TRIPLE_JUMP.M_CA9_TJ_ORDER', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.TRIPLE_JUMP', 'Puts the phases in the order jump, step, hop.', '{"question":"What is the order of the triple jump phases?","wrong_answer":"jump, step, hop","correct_answer":"hop, step, jump"}'::jsonb, 'The child knows the three words but not their order.', 'Offer "jump, step, hop" next to the right answer and ask the question again in a new context.', 'Say "hop, step, jump" while walking through it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.TRIPLE_JUMP.M_CA9_TJ_BIG_HOP', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.TRIPLE_JUMP', 'Makes the hop as big as possible and has no energy left for the jump.', '{"question":"Should the hop be as big as possible?","wrong_answer":"yes, the bigger the better","correct_answer":"no; the three phases should be balanced"}'::jsonb, 'The first phase feels like the most important.', 'Offer "yes, the bigger the better" next to the right answer and ask the question again in a new context.', 'Measure three jumps: one with a huge hop, one balanced.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.TRIPLE_JUMP.M_CA9_TJ_MEASURE', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.TRIPLE_JUMP', 'Measures the triple jump from where the jump phase starts.', '{"question":"Where is a triple jump measured from?","wrong_answer":"from where the last jump starts","correct_answer":"from the take-off board to the nearest mark in the pit"}'::jsonb, 'The child sees the last jump into the pit as the jump.', 'Offer "from where the last jump starts" next to the right answer and ask the question again in a new context.', 'Lay a tape from the board to the pit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.LONG_DISTANCE.M_CA9_LD_800', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.LONG_DISTANCE', 'Names the 800 m as a long distance race.', '{"question":"Which is a long distance race?","wrong_answer":"800 m","correct_answer":"10 000 m"}'::jsonb, 'The 800 m feels long to a learner.', 'Offer "800 m" next to the right answer and ask the question again in a new context.', 'Sort 100, 800, 1 500, 5 000 and 10 000 m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.LONG_DISTANCE.M_CA9_LD_FAST_START', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.LONG_DISTANCE', 'Starts a long race at sprint speed.', '{"question":"How should a long distance race be started?","wrong_answer":"as fast as possible","correct_answer":"at an even pace you can keep"}'::jsonb, 'Sprint starts were learnt first.', 'Offer "as fast as possible" next to the right answer and ask the question again in a new context.', 'Run two laps flat out from the start and two at even pace; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.LONG_DISTANCE.M_CA9_LD_LONG_STRIDE', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.LONG_DISTANCE', 'Uses long bounding strides in a long race.', '{"question":"Which stride suits a long distance race?","wrong_answer":"long bounding strides","correct_answer":"a short, relaxed, economical stride"}'::jsonb, 'Long strides look fast.', 'Offer "long bounding strides" next to the right answer and ask the question again in a new context.', 'Run 400 m bounding, then with short relaxed strides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.LONG_DISTANCE.M_CA9_LD_NO_WATER', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.LONG_DISTANCE', 'Thinks a runner should not drink water during a long race.', '{"question":"Should runners drink water in a long race?","wrong_answer":"no, it slows them","correct_answer":"yes, small sips at water points"}'::jsonb, 'The child thinks stopping for anything loses time.', 'Offer "no, it slows them" next to the right answer and ask the question again in a new context.', 'Talk about water points in the marathon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.MOSAIC.M_CA9_MS_PAINT', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.MOSAIC', 'Thinks a mosaic is painted in small dots.', '{"question":"How is a mosaic made?","wrong_answer":"by painting small dots","correct_answer":"by placing small pieces of material close together"}'::jsonb, 'Stippling (Grade 6) also uses small units.', 'Offer "by painting small dots" next to the right answer and ask the question again in a new context.', 'Compare a stippled drawing with a seed mosaic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.MOSAIC.M_CA9_MS_RANDOM', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.MOSAIC', 'Places mosaic pieces at random with no plan.', '{"question":"What comes before placing the mosaic pieces?","wrong_answer":"nothing; place them anywhere","correct_answer":"sketch the design and plan the colours"}'::jsonb, 'The child wants to start sticking straight away.', 'Offer "nothing; place them anywhere" next to the right answer and ask the question again in a new context.', 'Show a planned and an unplanned mosaic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.MOSAIC.M_CA9_MS_MIXED_MATERIALS', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.MOSAIC', 'Thinks a mosaic should mix many kinds of material like a collage.', '{"question":"Is a mosaic usually made of one kind of material or many?","wrong_answer":"many, like a collage","correct_answer":"one kind, such as seeds or tiles, in different colours"}'::jsonb, 'Mosaic and collage are both made of pieces.', 'Offer "many, like a collage" next to the right answer and ask the question again in a new context.', 'Compare a seed mosaic with a mixed collage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.MOSAIC.M_CA9_MS_BIG_PIECES', 'CREA.G9.CREATI.ATHLETICS_AND_MOSAIC.MOSAIC', 'Uses a few big pieces, losing the detail of the picture.', '{"question":"Why are mosaic pieces small?","wrong_answer":"they are cheaper","correct_answer":"small pieces show shapes and detail"}'::jsonb, 'Big pieces fill the space faster.', 'Offer "they are cheaper" next to the right answer and ask the question again in a new context.', 'Make the same shape with big and small pieces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.MELODY.VARIATION.M_CA9_VA_EXACT_COPY', 'CREA.G9.CREATI.MELODY.VARIATION', 'Thinks a variation is an exact copy of the phrase.', '{"question":"Is a variation the same as an exact repeat?","wrong_answer":"yes","correct_answer":"no; it repeats the phrase with a change"}'::jsonb, 'The child knows repetition and stops there.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Sing a phrase, then the same phrase with two notes changed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.MELODY.VARIATION.M_CA9_VA_ALL_NEW', 'CREA.G9.CREATI.MELODY.VARIATION', 'Changes every note, so the phrase is no longer recognisable.', '{"question":"A phrase is changed in every note and rhythm. Is it still a variation?","wrong_answer":"yes","correct_answer":"no; too much change loses the link to the first phrase"}'::jsonb, 'The child thinks more change is more creative.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Change only the rhythm, then only two pitches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.MELODY.VARIATION.M_CA9_VA_ONLY_PITCH', 'CREA.G9.CREATI.MELODY.VARIATION', 'Thinks only the pitches can be varied.', '{"question":"Name a way to vary a phrase other than changing pitches.","wrong_answer":"there is none","correct_answer":"change the rhythm, or move it higher or lower (sequence)"}'::jsonb, 'Pitch is the most noticeable change.', 'Offer "there is none" next to the right answer and ask the question again in a new context.', 'Vary a phrase by rhythm only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.MELODY.VARIATION.M_CA9_VA_END_ANYWHERE', 'CREA.G9.CREATI.MELODY.VARIATION', 'Ends an F major melody on C.', '{"question":"On which note should an F major melody end?","wrong_answer":"C","correct_answer":"F"}'::jsonb, 'C feels like home from earlier keys.', 'Offer "C" next to the right answer and ask the question again in a new context.', 'Sing the ending on C and on F.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.RUGBY.RUGBY.M_CA9_RU_FORWARD_PASS', 'CREA.G9.CREATI.RUGBY.RUGBY', 'Passes the rugby ball forward.', '{"question":"In which direction may a rugby ball be passed?","wrong_answer":"forward","correct_answer":"sideways or backwards"}'::jsonb, 'In football and netball the ball is passed forward.', 'Offer "forward" next to the right answer and ask the question again in a new context.', 'Walk through a line passing backwards as it moves forward.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.RUGBY.RUGBY.M_CA9_RU_SPIN_POP', 'CREA.G9.CREATI.RUGBY.RUGBY', 'Uses a spin pass for a team mate running right beside them.', '{"question":"Which pass suits a team mate running very close: spin or pop?","wrong_answer":"spin","correct_answer":"pop"}'::jsonb, 'The spin pass looks the most skilful.', 'Offer "spin" next to the right answer and ask the question again in a new context.', 'Try both to a close runner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.RUGBY.RUGBY.M_CA9_RU_DROP_PLACE', 'CREA.G9.CREATI.RUGBY.RUGBY', 'Calls a kick off a tee a drop kick.', '{"question":"A ball is kicked from a kicking tee. Which kick is it?","wrong_answer":"a drop kick","correct_answer":"a place kick"}'::jsonb, 'Both kicks start with the ball near the ground.', 'Offer "a drop kick" next to the right answer and ask the question again in a new context.', 'Show the tee for a place kick and the bounce for a drop kick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.RUGBY.RUGBY.M_CA9_RU_LOOK_BALL', 'CREA.G9.CREATI.RUGBY.RUGBY', 'Watches the ball instead of the catcher when passing.', '{"question":"Where should you look when passing in rugby?","wrong_answer":"at the ball in your hands","correct_answer":"at the target, the catcher''s hands"}'::jsonb, 'Beginners fear dropping the ball.', 'Offer "at the ball in your hands" next to the right answer and ask the question again in a new context.', 'Pass while calling out the catcher''s name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.PHOTOGRAPHY.VIEWPOINTS.M_CA9_VP_WORM_DOWN', 'CREA.G9.CREATI.PHOTOGRAPHY.VIEWPOINTS', 'Says the worm''s eye view looks down on the subject.', '{"question":"In a worm''s eye view, where is the camera?","wrong_answer":"high, looking down","correct_answer":"low, looking up"}'::jsonb, 'The child swaps the two named views.', 'Offer "high, looking down" next to the right answer and ask the question again in a new context.', 'Lie on the ground and look up at a tree.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.PHOTOGRAPHY.VIEWPOINTS.M_CA9_VP_BIRD_EFFECT', 'CREA.G9.CREATI.PHOTOGRAPHY.VIEWPOINTS', 'Thinks a bird''s eye view makes the subject look tall and powerful.', '{"question":"What does a bird''s eye view do to a person in the photo?","wrong_answer":"makes them look tall and powerful","correct_answer":"makes them look small"}'::jsonb, 'The child thinks height gives power to the subject.', 'Offer "makes them look tall and powerful" next to the right answer and ask the question again in a new context.', 'Photograph a friend from a staircase and from the ground.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.PHOTOGRAPHY.VIEWPOINTS.M_CA9_VP_NORMAL', 'CREA.G9.CREATI.PHOTOGRAPHY.VIEWPOINTS', 'Thinks the normal viewpoint is the worst one.', '{"question":"When is the normal (eye-level) view useful?","wrong_answer":"never","correct_answer":"when you want the subject to look natural"}'::jsonb, 'The child thinks unusual means better.', 'Offer "never" next to the right answer and ask the question again in a new context.', 'Compare eye-level and worm''s eye portraits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.PHOTOGRAPHY.VIEWPOINTS.M_CA9_VP_ZOOM', 'CREA.G9.CREATI.PHOTOGRAPHY.VIEWPOINTS', 'Thinks zooming in changes the viewpoint.', '{"question":"Does zooming in change the viewpoint?","wrong_answer":"yes","correct_answer":"no; the viewpoint is where the camera is, high, level or low"}'::jsonb, 'Zoom changes the picture, so it seems like a new viewpoint.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Zoom without moving, then move the camera low.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DESCANT_RECORDER.F_FINGERING.M_CA9_FF_B_FOR_BFLAT', 'CREA.G9.CREATI.DESCANT_RECORDER.F_FINGERING', 'Plays B flat with the fingering for B.', '{"question":"How do you play B flat on the recorder?","wrong_answer":"with the B fingering","correct_answer":"with its own cross-fingering"}'::jsonb, 'The child thinks a flat is played like the plain note.', 'Offer "with the B fingering" next to the right answer and ask the question again in a new context.', 'Play B, then B flat with the cross-fingering; hear the difference.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DESCANT_RECORDER.F_FINGERING.M_CA9_FF_LOW_F_LEFT', 'CREA.G9.CREATI.DESCANT_RECORDER.F_FINGERING', 'Plays low F with the left hand only.', '{"question":"Does low F need the right hand?","wrong_answer":"no, only the left hand","correct_answer":"yes, the left hand and most right-hand holes"}'::jsonb, 'Notes learnt so far used mostly the left hand.', 'Offer "no, only the left hand" next to the right answer and ask the question again in a new context.', 'Play low F slowly, covering the right-hand holes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DESCANT_RECORDER.F_FINGERING.M_CA9_FF_IGNORE_KEY', 'CREA.G9.CREATI.DESCANT_RECORDER.F_FINGERING', 'Ignores the flat in the key signature when sight reading.', '{"question":"A piece in F major has a B on the middle line. What do you play?","wrong_answer":"B","correct_answer":"B flat"}'::jsonb, 'The child reads each note alone and forgets the key signature.', 'Offer "B" next to the right answer and ask the question again in a new context.', 'Circle every B before playing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.DESCANT_RECORDER.F_FINGERING.M_CA9_FF_BLOW_LOW', 'CREA.G9.CREATI.DESCANT_RECORDER.F_FINGERING', 'Blows hard for low F, so it squeaks.', '{"question":"How should you blow for low F?","wrong_answer":"hard","correct_answer":"very gently"}'::jsonb, 'Big notes seem to need big breath.', 'Offer "hard" next to the right answer and ask the question again in a new context.', 'Play low F gently and then hard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.PLAY.SCRIPT_FORMAT.M_CA9_SF_QUOTES', 'CREA.G9.CREATI.PLAY.SCRIPT_FORMAT', 'Writes dialogue in quotation marks as in a story.', '{"question":"How is dialogue written in a play script?","wrong_answer":"in quotation marks, like a story","correct_answer":"after the character''s name, with no quotation marks"}'::jsonb, 'Stories use quotation marks, so the child copies that.', 'Offer "in quotation marks, like a story" next to the right answer and ask the question again in a new context.', 'Show a story page and a script page side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.PLAY.SCRIPT_FORMAT.M_CA9_SF_DIRECTIONS_PLAIN', 'CREA.G9.CREATI.PLAY.SCRIPT_FORMAT', 'Writes stage directions as plain lines like dialogue.', '{"question":"How are stage directions shown in a script?","wrong_answer":"as ordinary lines","correct_answer":"in brackets or italics"}'::jsonb, 'The child does not know scripts mark them differently.', 'Offer "as ordinary lines" next to the right answer and ask the question again in a new context.', 'Underline every stage direction in a sample script.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.PLAY.SCRIPT_FORMAT.M_CA9_SF_NO_CAST', 'CREA.G9.CREATI.PLAY.SCRIPT_FORMAT', 'Leaves out the cast list.', '{"question":"What comes at the start of a play script, after the title?","wrong_answer":"the first line of dialogue","correct_answer":"the cast list (characters)"}'::jsonb, 'Stories start straight away, so the child does too.', 'Offer "the first line of dialogue" next to the right answer and ask the question again in a new context.', 'Read the first page of a published play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.PLAY.SCRIPT_FORMAT.M_CA9_SF_SCENE_ACT', 'CREA.G9.CREATI.PLAY.SCRIPT_FORMAT', 'Thinks a scene is bigger than an act.', '{"question":"Which is bigger: an act or a scene?","wrong_answer":"a scene","correct_answer":"an act; it is made of scenes"}'::jsonb, 'Scenes are what the child notices changing.', 'Offer "a scene" next to the right answer and ask the question again in a new context.', 'Show a contents page: Act 1, Scenes 1-3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.BASKETBALL.M_CA9_BB_TRAVEL', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.BASKETBALL', 'Walks with the ball without dribbling.', '{"question":"May you walk with the basketball in your hands?","wrong_answer":"yes","correct_answer":"no; that is travelling"}'::jsonb, 'In rugby players run with the ball.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Walk with the ball and blow the whistle: travelling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.BASKETBALL.M_CA9_BB_DOUBLE', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.BASKETBALL', 'Dribbles, stops, then dribbles again.', '{"question":"After you stop dribbling, may you dribble again?","wrong_answer":"yes","correct_answer":"no; that is a double dribble"}'::jsonb, 'The child thinks dribbling can restart any time.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Dribble, catch, then try again: whistle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.BASKETBALL.M_CA9_BB_HIGH_LOW', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.BASKETBALL', 'Uses a high dribble near a defender.', '{"question":"Which dribble protects the ball near a defender?","wrong_answer":"a high dribble","correct_answer":"a low dribble"}'::jsonb, 'High dribbles are faster, so the child uses them everywhere.', 'Offer "a high dribble" next to the right answer and ask the question again in a new context.', 'Dribble high past a defender, then low; who keeps it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.BASKETBALL.M_CA9_BB_PASS_CHOICE', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.BASKETBALL', 'Uses a chest pass over a defender''s raised arms.', '{"question":"Which pass goes over a defender with raised arms?","wrong_answer":"the chest pass","correct_answer":"the overhead pass"}'::jsonb, 'The chest pass is the first one learnt.', 'Offer "the chest pass" next to the right answer and ask the question again in a new context.', 'Pass to a team mate behind a defender with raised arms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.LOGO.M_CA9_LG_DETAIL', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.LOGO', 'Thinks a good logo is full of detail.', '{"question":"Is a good logo simple or detailed?","wrong_answer":"detailed, with many pictures","correct_answer":"simple and easy to recognise"}'::jsonb, 'Detail looks like effort.', 'Offer "detailed, with many pictures" next to the right answer and ask the question again in a new context.', 'Shrink a busy logo and a simple one to stamp size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.LOGO.M_CA9_LG_MANY_COLOURS', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.LOGO', 'Uses many colours in a logo.', '{"question":"How many colours should a team logo usually use?","wrong_answer":"as many as possible","correct_answer":"a few, often two or three"}'::jsonb, 'Bright colours seem attractive.', 'Offer "as many as possible" next to the right answer and ask the question again in a new context.', 'Print a logo in black only: does it still work?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.LOGO.M_CA9_LG_NO_MEANING', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.LOGO', 'Picks a picture that has nothing to do with the team.', '{"question":"What should a team logo show?","wrong_answer":"any picture you like","correct_answer":"something linked to the team''s name or spirit"}'::jsonb, 'The child chooses a favourite picture.', 'Offer "any picture you like" next to the right answer and ask the question again in a new context.', 'Brainstorm the team name and what it stands for first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.LOGO.M_CA9_LG_COPY', 'CREA.G9.CREATI.BASKETBALL_AND_LOGO_DESI.LOGO', 'Copies a famous team''s logo.', '{"question":"May you copy a famous club''s logo for your team?","wrong_answer":"yes","correct_answer":"no; design your own"}'::jsonb, 'Famous logos look good, so copying seems fine.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Discuss why every team needs its own identity.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.COIL_POTTERY.M_CA9_CP_NO_WEDGE', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.COIL_POTTERY', 'Skips wedging the clay.', '{"question":"Why is clay wedged before making coils?","wrong_answer":"it is not needed","correct_answer":"to remove air bubbles so the pot does not crack"}'::jsonb, 'The child is eager to start shaping.', 'Offer "it is not needed" next to the right answer and ask the question again in a new context.', 'Cut a lump of unwedged clay and show the air pockets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.COIL_POTTERY.M_CA9_CP_UNEVEN', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.COIL_POTTERY', 'Rolls coils of different thickness.', '{"question":"Why roll coils of even thickness?","wrong_answer":"it does not matter","correct_answer":"so the walls are even and dry without cracking"}'::jsonb, 'The child rolls quickly by eye.', 'Offer "it does not matter" next to the right answer and ask the question again in a new context.', 'Roll coils against a guide stick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.COIL_POTTERY.M_CA9_CP_NO_SLIP', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.COIL_POTTERY', 'Presses coils together without scoring or slip.', '{"question":"How are coils joined firmly?","wrong_answer":"just press them together","correct_answer":"score and join with slip, then smooth"}'::jsonb, 'Wet clay feels sticky enough.', 'Offer "just press them together" next to the right answer and ask the question again in a new context.', 'Join two coils with and without slip; let them dry and test.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.COIL_POTTERY.M_CA9_CP_DRY_SUN', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.COIL_POTTERY', 'Dries the pot in hot sun to finish quickly.', '{"question":"Where should a coil pot dry?","wrong_answer":"in hot sun","correct_answer":"slowly in the shade"}'::jsonb, 'Sun dries things fast.', 'Offer "in hot sun" next to the right answer and ask the question again in a new context.', 'Compare a pot dried in sun (cracks) with one in shade.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.TWILL.M_CA9_TW_PLAIN', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.TWILL', 'Thinks 2/1 twill is over one, under one.', '{"question":"In a 2/1 twill, how does the weft pass the warp?","wrong_answer":"over one, under one","correct_answer":"over two, under one"}'::jsonb, 'Plain weave was learnt first.', 'Offer "over one, under one" next to the right answer and ask the question again in a new context.', 'Weave three rows of each and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.TWILL.M_CA9_TW_NO_SHIFT', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.TWILL', 'Starts every row at the same place, so no diagonal forms.', '{"question":"Why does a twill show diagonal lines?","wrong_answer":"it does not","correct_answer":"each row moves one warp thread along"}'::jsonb, 'The child repeats the first row exactly.', 'Offer "it does not" next to the right answer and ask the question again in a new context.', 'Weave four rows, shifting one thread each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.TWILL.M_CA9_TW_WARP_WEFT', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.TWILL', 'Calls the threads stretched on the frame the weft.', '{"question":"What are the threads stretched tight on a frame loom called?","wrong_answer":"the weft","correct_answer":"the warp"}'::jsonb, 'The two words are easy to swap.', 'Offer "the weft" next to the right answer and ask the question again in a new context.', 'Warp goes on the loom first; weft goes across.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.TWILL.M_CA9_TW_LOOSE_WARP', 'CREA.G9.CREATI.INDIGENOUS_KENYAN_CRAFTS.TWILL', 'Leaves the warp loose on the frame.', '{"question":"Why must the warp be tight on a frame loom?","wrong_answer":"it does not matter","correct_answer":"so the weave is even and does not sag"}'::jsonb, 'The child ties the warp quickly.', 'Offer "it does not matter" next to the right answer and ask the question again in a new context.', 'Weave on a loose warp and a tight one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.SWIMMING.DIVE_BUTTERFLY.M_CA9_DB_SHALLOW', 'CREA.G9.CREATI.SWIMMING.DIVE_BUTTERFLY', 'Thinks a standing dive is safe in shallow water.', '{"question":"Where may you do a standing dive?","wrong_answer":"anywhere in the pool","correct_answer":"only into deep water with a lifeguard"}'::jsonb, 'Confident swimmers feel safe everywhere.', 'Offer "anywhere in the pool" next to the right answer and ask the question again in a new context.', 'Show the depth markings; talk about head injuries.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.SWIMMING.DIVE_BUTTERFLY.M_CA9_DB_FEET_FIRST', 'CREA.G9.CREATI.SWIMMING.DIVE_BUTTERFLY', 'Thinks a standing dive enters feet first.', '{"question":"Which part enters the water first in a standing dive?","wrong_answer":"the feet","correct_answer":"the hands, arms stretched over the head"}'::jsonb, 'The pencil dive (Grade 7) entered feet first.', 'Offer "the feet" next to the right answer and ask the question again in a new context.', 'Practise the arm position on land: hands together over the head.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.SWIMMING.DIVE_BUTTERFLY.M_CA9_DB_ARMS_ALTERNATE', 'CREA.G9.CREATI.SWIMMING.DIVE_BUTTERFLY', 'Moves the arms one after the other in butterfly.', '{"question":"In butterfly, do the arms move together or one after another?","wrong_answer":"one after another","correct_answer":"together"}'::jsonb, 'Front crawl arms alternate.', 'Offer "one after another" next to the right answer and ask the question again in a new context.', 'Practise both arms together on land.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.SWIMMING.DIVE_BUTTERFLY.M_CA9_DB_FROG_KICK', 'CREA.G9.CREATI.SWIMMING.DIVE_BUTTERFLY', 'Uses a frog kick in butterfly.', '{"question":"Which kick is used in butterfly?","wrong_answer":"the frog kick","correct_answer":"the dolphin kick, legs together"}'::jsonb, 'Breaststroke also moves both arms together, with a frog kick.', 'Offer "the frog kick" next to the right answer and ask the question again in a new context.', 'Kick with legs together like a dolphin tail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_.BOARD_GAMES.M_CA9_BG_CHESS', 'CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_.BOARD_GAMES', 'Names chess or draughts as an indigenous Kenyan board game.', '{"question":"Which is an indigenous Kenyan board game?","wrong_answer":"chess","correct_answer":"bao (a game of sowing seeds in pits)"}'::jsonb, 'Chess and draughts are the board games the child knows.', 'Offer "chess" next to the right answer and ask the question again in a new context.', 'Compare a chess board with a bao board of pits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_.BOARD_GAMES.M_CA9_BG_LUCK', 'CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_.BOARD_GAMES', 'Thinks board games like bao depend only on luck.', '{"question":"Does winning at bao depend only on luck?","wrong_answer":"yes","correct_answer":"no; it needs counting and planning ahead"}'::jsonb, 'There is no thinking visible when seeds are dropped.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Play a round and plan two moves ahead.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_.BOARD_GAMES.M_CA9_BG_BENEFIT', 'CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_.BOARD_GAMES', 'Thinks board games have no benefit because they are not active.', '{"question":"Name a benefit of indigenous board games.","wrong_answer":"none; you sit still","correct_answer":"any of: counting, planning, patience, mental health, social time"}'::jsonb, 'The child links benefit only with physical fitness.', 'Offer "none; you sit still" next to the right answer and ask the question again in a new context.', 'List what the mind does in one game.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_.BOARD_GAMES.M_CA9_BG_SOW_SKIP', 'CREA.G9.CREATI.KENYAN_INDIGENOUS_GAMES_.BOARD_GAMES', 'Drops several seeds in one pit when sowing.', '{"question":"When sowing in bao, how many seeds go in each pit?","wrong_answer":"as many as you like","correct_answer":"one seed in each pit in turn"}'::jsonb, 'The child hurries to empty the hand.', 'Offer "as many as you like" next to the right answer and ask the question again in a new context.', 'Sow slowly, counting one per pit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.PERFORMANCE_ANALYSIS.M_CA9_PA_OPINION', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.PERFORMANCE_ANALYSIS', 'Analyses a play only by saying it was nice.', '{"question":"Which is an analysis of a play performance?","wrong_answer":"it was nice","correct_answer":"the actor''s shaking voice showed the father''s fear, which built the conflict"}'::jsonb, 'Giving an opinion feels like analysing.', 'Offer "it was nice" next to the right answer and ask the question again in a new context.', 'Ask "what did you see or hear that shows that?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.PERFORMANCE_ANALYSIS.M_CA9_PA_DICTION', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.PERFORMANCE_ANALYSIS', 'Thinks diction in a song means how loud it is.', '{"question":"What is diction in a solo vocal piece?","wrong_answer":"how loud it is","correct_answer":"how clearly the words are pronounced"}'::jsonb, 'The child mixes diction with dynamics.', 'Offer "how loud it is" next to the right answer and ask the question again in a new context.', 'Sing a line mumbling and then clearly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.PERFORMANCE_ANALYSIS.M_CA9_PA_ACCOMPANIMENT', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.PERFORMANCE_ANALYSIS', 'Thinks a solo vocal piece can have no accompaniment by definition.', '{"question":"Can a solo vocal piece have an accompaniment?","wrong_answer":"no, solo means alone","correct_answer":"yes; one singer may be accompanied by instruments"}'::jsonb, 'The child takes "solo" to mean no other sound.', 'Offer "no, solo means alone" next to the right answer and ask the question again in a new context.', 'Listen to a soloist with a guitar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.PERFORMANCE_ANALYSIS.M_CA9_PA_AUDIENCE', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.PERFORMANCE_ANALYSIS', 'Leaves out how the actors involve the audience.', '{"question":"Name one thing to look for when analysing a play performance.","wrong_answer":"only the costumes","correct_answer":"any of: theme, conflict, use of voice and body, props, costume, audience involvement"}'::jsonb, 'Costumes are the most visible part.', 'Offer "only the costumes" next to the right answer and ask the question again in a new context.', 'Use the full analysis checklist.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_ETHICS.M_CA9_SE_DOPING_OK_SMALL', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_ETHICS', 'Thinks a small amount of a banned drug is acceptable.', '{"question":"Is a small amount of a banned substance allowed?","wrong_answer":"yes, if it is small","correct_answer":"no; any banned substance is doping"}'::jsonb, 'The child thinks only large amounts count.', 'Offer "yes, if it is small" next to the right answer and ask the question again in a new context.', 'Read an anti-doping rule together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_ETHICS.M_CA9_SE_AGE_CHEAT', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_ETHICS', 'Thinks lying about age to play in a younger group is harmless.', '{"question":"Is it fair to lie about age to play in a younger team?","wrong_answer":"yes, it helps the team win","correct_answer":"no; it is cheating and unfair to younger players"}'::jsonb, 'The child focuses on winning.', 'Offer "yes, it helps the team win" next to the right answer and ask the question again in a new context.', 'Discuss how the younger players feel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_ETHICS.M_CA9_SE_MATCH_FIXING', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_ETHICS', 'Thinks losing a match on purpose for money is a private choice.', '{"question":"A player is paid to lose a match on purpose. Is that ethical?","wrong_answer":"yes, it is their choice","correct_answer":"no; it is match fixing and cheats everyone"}'::jsonb, 'The child sees the choice as affecting only the player.', 'Offer "yes, it is their choice" next to the right answer and ask the question again in a new context.', 'Talk about fans, team mates and the sport.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_ETHICS.M_CA9_SE_DOPING_ONLY_HEALTH', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_ETHICS', 'Thinks doping is banned only because it is unhealthy.', '{"question":"Give two reasons why doping is banned.","wrong_answer":"only because it is unhealthy","correct_answer":"it is cheating, and it harms health"}'::jsonb, 'Health warnings are what the child has heard.', 'Offer "only because it is unhealthy" next to the right answer and ask the question again in a new context.', 'Discuss what doping does to fairness.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE.M_CA9_CQ_JUDGE_FIRST', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE', 'Starts a critique by judging before describing.', '{"question":"What is the first step of a critique?","wrong_answer":"say if it is good or bad","correct_answer":"describe what you see"}'::jsonb, 'Judging is the quickest response.', 'Offer "say if it is good or bad" next to the right answer and ask the question again in a new context.', 'Use the four steps: describe, analyse, interpret, judge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE.M_CA9_CQ_NO_REASON', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE', 'Judges an artwork without giving reasons.', '{"question":"Which is a good critique judgement?","wrong_answer":"it is bad","correct_answer":"it works because the warm colours draw the eye to the dancer"}'::jsonb, 'The child thinks an opinion is enough.', 'Offer "it is bad" next to the right answer and ask the question again in a new context.', 'Add "because" to every judgement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE.M_CA9_CQ_ARTIST_PERSON', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE', 'Comments on the artist as a person instead of the work.', '{"question":"What should a critique comment on?","wrong_answer":"whether the artist is a nice person","correct_answer":"the artwork itself"}'::jsonb, 'The child knows the artist and mixes the two.', 'Offer "whether the artist is a nice person" next to the right answer and ask the question again in a new context.', 'Cover the name and critique the work only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE.M_CA9_CQ_INTERPRET_DESCRIBE', 'CREA.G9.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE', 'Gives a description when asked for the meaning.', '{"question":"What is the interpretation step of a critique?","wrong_answer":"listing what is in the picture","correct_answer":"saying what the work means or expresses"}'::jsonb, 'Describing is easier than interpreting.', 'Offer "listing what is in the picture" next to the right answer and ask the question again in a new context.', 'Ask "what is the artist telling us?" after describing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
